import { test, expect } from '@playwright/test';

test.describe('Shopping Cart - Add and Remove Product', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should add a product to the cart and update cart badge', async ({ page }) => {
    // Login as standard_user
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('standard_user@example.com');
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('secret_sauce');
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify successful login
    const welcomeMessage = page.getByText(/Welcome, standard_user/i);
    await expect(welcomeMessage).toBeVisible();

    // Navigate to product page
    const productLink = page.getByRole('link', { name: /sauce labs backpack/i });
    await productLink.click();

    // Verify product page is loaded
    const productName = page.getByText(/sauce labs backpack/i);
    await expect(productName).toBeVisible();

    // Click add to cart button
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await addToCartButton.click();

    // Verify cart badge shows '1'
    const cartBadge = page.getByTestId('shopping_cart_badge');
    await expect(cartBadge).toContainText('1');

    // Verify button label changes to 'Remove'
    const removeButton = page.getByRole('button', { name: /remove/i });
    await expect(removeButton).toBeVisible();

    // Verify remove button is enabled
    await expect(removeButton).toBeEnabled();
  });

  test('should remove a product from the cart and update cart badge', async ({ page }) => {
    // Login as standard_user
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('standard_user@example.com');
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('secret_sauce');
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify successful login
    const welcomeMessage = page.getByText(/Welcome, standard_user/i);
    await expect(welcomeMessage).toBeVisible();

    // Navigate to product page
    const productLink = page.getByRole('link', { name: /sauce labs backpack/i });
    await productLink.click();

    // Verify product page is loaded
    const productName = page.getByText(/sauce labs backpack/i);
    await expect(productName).toBeVisible();

    // Click add to cart button
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await addToCartButton.click();

    // Verify cart badge shows '1'
    const cartBadge = page.getByTestId('shopping_cart_badge');
    await expect(cartBadge).toContainText('1');

    // Click remove button
    const removeButton = page.getByRole('button', { name: /remove/i });
    await removeButton.click();

    // Verify cart badge shows '0'
    await expect(cartBadge).toContainText('0');

    // Verify remove button is disabled
    await expect(removeButton).toBeDisabled();
  });
});
